"""Package the shrub shadow correction using unchanged standalone game images."""
from pathlib import Path
import json,shutil,hashlib
from PIL import Image,ImageDraw,ImageFont
from measure_perceived_detail import run
ROOT=Path('C:/GrandTour');QA=ROOT/'Saved/LidarAuthoringQA/ShrubShadows';CAP=ROOT/'Saved/LidarAuthoringQA/RS7';OUT=ROOT/'Art/Export/LidarStudy/FirstSection/Review/ShrubShadows';OUT.mkdir(parents=True,exist_ok=True)
a,b=run('shrub-shadow-before'),run('shrub-shadow-after');assert a['views']==b['views'] and a['commands']==b['commands']
installed=json.loads((QA/'installed.json').read_text());audit=json.loads((QA/'audit.json').read_text());assert installed['ok'] and installed['planting']==audit['planting']
metrics={}
for view in a['views']:
 v=view['view'];metrics[v]=dict(before=a['measurements'][v]['GPUTime']['median'],after=b['measurements'][v]['GPUTime']['median']);metrics[v]['delta']=metrics[v]['after']-metrics[v]['before']
 for side,label in [('before',a['label']),('after',b['label'])]:shutil.copy2(CAP/f'{label}-{v}.png',OUT/f'{side}-{v}.png')
evidence=dict(cause='Cast Shadow was false on all 2446 woody shrubs and 152 authored bank plants; all mesh sections already supported casting.',fix=installed,audit=audit,before=a,after=b,metrics=metrics,map_sha256=hashlib.sha256((ROOT/'Content/GrandTour/ArtTests/LidarStudy/L_LidarStudy.umap').read_bytes()).hexdigest(),performance_method='One warmed standalone A/B pair, same 1600x900 v6 preset and cameras. Indicative cost only; this does not certify the prior +1 ms target or eliminate thermal variation.',scope='Component shadow flags only. No new plants or geometry, no material, lighting, exposure, transform, cull-distance or collision changes.')
evidence['visual_observation']='Sunlit shrubs visibly self-shadow and cast onto grass; the already shaded bank has limited visible change despite its higher rendering cost.'
if (QA/'process-status.json').exists():evidence['process_status']=json.loads((QA/'process-status.json').read_text())
(OUT/'evidence.json').write_text(json.dumps(evidence,indent=2))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shrub shadows - actual game comparison</title><style>body{margin:24px;background:#14221b;color:#ecf2e8;font:16px/1.5 system-ui}main{max-width:1700px;margin:auto}h1{font-size:28px}p{max-width:1000px}a{color:#b3ddb2}button{background:#36523d;border:1px solid #789076;color:white;font:inherit;padding:9px 16px;cursor:pointer}nav{display:flex;gap:10px;margin:20px 0}.views{display:grid;grid-template-columns:1fr 1fr;gap:16px}.views img{width:100%}h2{font-size:19px}td,th{padding:6px 20px 6px 0;text-align:left}table{border-collapse:collapse}tr{border-bottom:1px solid #4a5b4f}@media(max-width:900px){.views{grid-template-columns:1fr}}</style><main><h1>Restoring shadows on shrubs and bank plants</h1><p>The components had shadow casting disabled. Dynamic shadows and two-sided leaf shadow casting are now enabled on 2,446 shrubs and 152 bank plants. Placement, materials, light, exposure and collision are unchanged.</p><nav><button onclick="choose('F01')">Shrubs by the field</button><button onclick="choose('D01')">Bank close-up</button><button onclick="choose('B01')">Riverbank</button><button onclick="choose('B04')">Across the river</button></nav><div class="views"><section><h2>Before</h2><a id="beforeLink"><img id="before" alt="Actual game before shadow correction"></a></section><section><h2>After</h2><a id="afterLink"><img id="after" alt="Actual game with shrub shadows"></a></section></div><p>Unretouched game captures. Click an image for full resolution.</p><p>The sunlit shrubs now show clear self-shadowing and shadows on the grass. The bank is already shaded by terrain and canopy, so its visible change is limited despite the higher rendering cost.</p><h2>Measured cost</h2><p>One warmed A/B pair, same v6 preset and 1600 x 900 output. These timings are indicative; thermal variation remains and the earlier +1 ms target is not certified by this check.</p><table><tr><th>View</th><th>Before GPU ms</th><th>After GPU ms</th><th>Change</th></tr>ROWS</table><p>Plant-position hashes, terrain and root-contact checks pass. <a href="evidence.json">Full evidence</a> · <a href="../PerceivedDetail/index.html">Earlier detail comparison and original/site references</a></p></main><script>function choose(v){for(const side of ['before','after']){const path=side+'-'+v+'.png';document.getElementById(side).src=path;document.getElementById(side+'Link').href=path}}choose('F01');</script></html>'''
page=page.replace('ROWS',''.join(f'<tr><td>{v}</td><td>{m["before"]:.2f}</td><td>{m["after"]:.2f}</td><td>{m["delta"]:+.2f} ms</td></tr>' for v,m in metrics.items()));(OUT/'index.html').write_text(page,encoding='utf-8')
board=Image.new('RGB',(1600,1040),'#14221b');draw=ImageDraw.Draw(board);font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',24)
for row,v in enumerate(['F01','D01']):
 for col,side in enumerate(['before','after']):
  x=col*800;y=row*510;draw.text((x+16,y+10),('Shrubs' if v=='F01' else 'Bank plants')+' - '+side,font=font,fill='white');board.paste(Image.open(OUT/f'{side}-{v}.png').resize((800,450),Image.Resampling.LANCZOS),(x,y+48))
board.save(OUT/'comparison.jpg',quality=95)
p=ROOT/'Art/Export/LidarStudy/Place/first-section.json';m=json.loads(p.read_text());m.update(latest_shadow_review=str(OUT/'index.html'),latest_shadow_evidence=str(OUT/'evidence.json'),map_sha256=evidence['map_sha256']);p.write_text(json.dumps(m,indent=2))
for parent in [OUT.parent/'index.html',OUT.parent/'PerceivedDetail/index.html']:
 text=parent.read_text(encoding='utf-8');link='ShrubShadows/index.html' if parent.parent==OUT.parent else '../ShrubShadows/index.html'
 if link not in text:
  text=text.replace('<main>','<main><p><a href="'+link+'">Latest correction: shrub and bank-plant shadows</a></p>',1);parent.write_text(text,encoding='utf-8')
entry='\n\nSHRUB SHADOW CORRECTION - 2026-11-06\nRestored dynamic and two-sided shadow casting on 2446 woody shrubs and 152 RS7 bank plants (2598 unchanged transforms). The earlier no-shadow foliage policy removed self-shadowing and ground anchoring; mesh sections already supported shadows. Corrected the installation, reference-style, bank planting, river-variety, river-detail and first-section authoring rules. Planting hashes, terrain and root-contact checks pass.\nActual before/after review: Art/Export/LidarStudy/FirstSection/Review/ShrubShadows/index.html\nSingle warmed A/B GPU deltas (indicative; thermal variation and prior +1 ms gate remain unresolved): '+', '.join(v+' '+format(m['delta'],'+.2f')+' ms' for v,m in metrics.items())+'.\nBackup: '+str(json.loads((QA/'backup.json').read_text())['backup'])+'\n'
for name in ['docs/LIDAR_PLACE_PLAN.md','docs/LidarStudy.txt']:
 p=ROOT/name
 if b'SHRUB SHADOW CORRECTION - 2026-11-06' not in p.read_bytes():
  with p.open('ab') as f:f.write(entry.encode('ascii'))
print(json.dumps(metrics,indent=2));print(OUT/'index.html')
